// Generated by SHAPI for advisory quickbooks-minorversion-below-75-ignored: Minor versions below 75 are silently answered as minor version 75
// Call site: src/accounting.ts:7 (GET /v3/company/{realmId}/query, via fetch)
// The provider no longer accepts the old request: fetch is replaced by a stub that answers it
// with 410, and answers anything else with a body holding the fields the code reads. The test
// fails until openInvoices() sends the new request (minorversion=75) and still works.
import { afterEach, describe, expect, it, vi } from "vitest";

type ShapiRequest = { method: string; url: string; headers: Record<string, string>; body?: unknown };
type ShapiResponse = { status: number; body: unknown; headers: Record<string, string> };
const shapi = vi.hoisted(() => ({
  respond: (_req: { method: string; url: string; headers: Record<string, string>; body?: unknown }): { status: number; body: unknown; headers: Record<string, string> } => ({ status: 200, body: null, headers: {} }),
  lower: (h: unknown): Record<string, string> =>
    Object.fromEntries(Object.entries((h ?? {}) as Record<string, unknown>).filter(([, v]) => v !== undefined).map(([k, v]) => [k.toLowerCase(), String(v)])),
}));

import { openInvoices } from "../../src/accounting";

const shapiFetch = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
  const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
  // forEach rather than entries(): it type-checks without the "dom.iterable" lib.
  const headers: Record<string, string> = {};
  new Headers(init?.headers ?? (input instanceof Request ? input.headers : undefined)).forEach((value, name) => {
    headers[name] = value;
  });
  let body: unknown = init?.body ?? undefined;
  if (typeof body === "string") {
    try {
      body = JSON.parse(body);
    } catch {
      // a form or text body stays as it is
    }
  }
  const res = shapi.respond({ method: (init?.method ?? (input instanceof Request ? input.method : "GET")).toUpperCase(), url, headers, body });
  return new Response(res.body === null ? null : JSON.stringify(res.body), { status: res.status, headers: res.headers });
});

afterEach(() => {
  vi.unstubAllGlobals();
});

async function run(respond: (req: ShapiRequest) => ShapiResponse): Promise<unknown> {
  shapi.respond = respond;
  vi.stubGlobal("fetch", shapiFetch);
  return openInvoices("shapi-realmId", "shapi-accessToken");
}

/** Marks a failure as the API change itself, as opposed to anything else going wrong in the test. */
function breakage(err: unknown, what: string): unknown {
  if (!(err instanceof Error)) return new Error(`SHAPI breakage: ${what}: ${String(err)}`);
  err.message = `SHAPI breakage: ${what}: ${err.message}`;
  return err;
}

const body = {"QueryResponse":{"Invoice":"shapi QueryResponse.Invoice"}};

function retired(req: ShapiRequest): boolean {
  const url = new URL(req.url, "https://shapi.invalid");
  return (url.searchParams.has("minorversion") && Number(url.searchParams.get("minorversion")) < 75);
}

describe("SHAPI contract: quickbooks-minorversion-below-75-ignored", () => {
  it("openInvoices sends the new request and handles the response", async () => {
    const sent: boolean[] = [];
    let error: unknown;
    await run((req) => {
      const old = retired(req);
      sent.push(old);
      return old ? { status: 410, body: { error: "retired request (SHAPI contract test)" }, headers: { "content-type": "application/json" } } : { status: 200, body, headers: { "content-type": "application/json" } };
    }).catch((err: unknown) => {
      error = err;
    });
    // Failing before any request is not the API change: the arguments or the environment are off.
    if (sent.length === 0) throw error ?? new Error("openInvoices() sent no request");
    if (sent.includes(true)) throw breakage(error ?? new Error("the provider no longer accepts it"), "openInvoices() sent the retired request");
    if (error) throw error;
  });
});
